// ElectricalAI Pro Load Calculation
const projectData = $input.first().json;

// Extract project parameters
const {
  projectType = 'residential',
  squareFootage = 2000,
  complexityLevel = 'standard',
  location = 'general',
  specialRequirements = []
} = projectData;

// NEC 2023 Load Calculations
function calculateElectricalLoad(sqft, type, complexity) {
  let baseLoad = 0;
  let lightingLoad = sqft * 3; // 3 VA per sq ft (NEC 220.12)

  // Small appliance circuits (NEC 220.52)
  let applianceLoad = 3000; // Minimum 2 circuits at 1500 VA each

  // Additional loads based on project type
  switch(type.toLowerCase()) {
    case 'residential':
      baseLoad = lightingLoad + applianceLoad;
      if (sqft > 3000) baseLoad += (sqft - 3000) * 1; // Additional for larger homes
      break;
    case 'commercial':
      baseLoad = sqft * 3.5; // Higher load factor for commercial
      break;
    case 'industrial':
      baseLoad = sqft * 5; // Industrial requirements
      break;
  }

  // Complexity multiplier
  const complexityMultiplier = {
    'simple': 0.8,
    'standard': 1.0,
    'complex': 1.3,
    'high-end': 1.6
  };

  return Math.round(baseLoad * (complexityMultiplier[complexity] || 1.0));
}

// Calculate circuit requirements
function calculateCircuits(totalLoad) {
  const circuits = {
    lighting: Math.ceil(totalLoad * 0.4 / 1800), // 15A circuits at 80% capacity
    outlets: Math.ceil(totalLoad * 0.3 / 1800),
    appliance: Math.ceil(totalLoad * 0.2 / 3600), // 20A circuits
    special: Math.ceil(totalLoad * 0.1 / 3600)
  };

  return {
    ...circuits,
    total: Object.values(circuits).reduce((sum, count) => sum + count, 0)
  };
}

// Material estimation
function estimateMaterials(circuits, sqft) {
  const materials = {
    wire: {
      '12AWG': circuits.outlets * 150, // feet
      '14AWG': circuits.lighting * 150,
      '10AWG': circuits.appliance * 50
    },
    conduit: Math.ceil(sqft / 100) * 10, // 10ft sections
    outlets: circuits.outlets * 8, // outlets per circuit
    switches: circuits.lighting * 4,
    panels: circuits.total > 20 ? 2 : 1,
    breakers: circuits.total
  };

  return materials;
}

// Cost estimation (RS Means based)
function calculateCosts(materials, location) {
  const baseCosts = {
    wire12AWG: 2.50, // per foot
    wire14AWG: 1.80,
    wire10AWG: 3.20,
    conduit: 8.50, // per 10ft section
    outlet: 15.00,
    switch: 12.00,
    panel100A: 450.00,
    panel200A: 650.00,
    breaker: 25.00,
    labor: 85.00 // per hour
  };

  // Location multiplier
  const locationMultiplier = {
    'urban': 1.2,
    'suburban': 1.0,
    'rural': 0.9,
    'general': 1.0
  };

  const multiplier = locationMultiplier[location.toLowerCase()] || 1.0;

  const materialCost = (
    (materials.wire['12AWG'] * baseCosts.wire12AWG) +
    (materials.wire['14AWG'] * baseCosts.wire14AWG) +
    (materials.wire['10AWG'] * baseCosts.wire10AWG) +
    (materials.conduit * baseCosts.conduit) +
    (materials.outlets * baseCosts.outlet) +
    (materials.switches * baseCosts.switch) +
    (materials.panels * (materials.panels > 1 ? baseCosts.panel200A : baseCosts.panel100A)) +
    (materials.breakers * baseCosts.breaker)
  ) * multiplier;

  const laborHours = Math.ceil(materialCost / 100); // Rough estimate
  const laborCost = laborHours * baseCosts.labor * multiplier;

  return {
    materials: Math.round(materialCost),
    labor: Math.round(laborCost),
    total: Math.round(materialCost + laborCost),
    breakdown: {
      wire: Math.round((materials.wire['12AWG'] * baseCosts.wire12AWG + 
                       materials.wire['14AWG'] * baseCosts.wire14AWG + 
                       materials.wire['10AWG'] * baseCosts.wire10AWG) * multiplier),
      devices: Math.round((materials.outlets * baseCosts.outlet + 
                          materials.switches * baseCosts.switch) * multiplier),
      panels: Math.round(materials.panels * (materials.panels > 1 ? baseCosts.panel200A : baseCosts.panel100A) * multiplier),
      conduit: Math.round(materials.conduit * baseCosts.conduit * multiplier),
      labor: Math.round(laborCost)
    }
  };
}

// Perform calculations
const totalLoad = calculateElectricalLoad(squareFootage, projectType, complexityLevel);
const circuits = calculateCircuits(totalLoad);
const materials = estimateMaterials(circuits, squareFootage);
const costs = calculateCosts(materials, location);

// Compliance notes
const complianceNotes = [
  'Design follows NEC 2023 standards',
  'Load calculations per NEC Article 220',
  'GFCI protection required in wet locations',
  'AFCI protection required in living areas',
  `Panel capacity: ${circuits.total > 20 ? '200A' : '100A'} service recommended`
];

// Return comprehensive estimation
return [{
  json: {
    projectId: projectData.projectId || `EST-${Date.now()}`,
    timestamp: new Date().toISOString(),
    input: projectData,
    calculations: {
      totalLoad,
      circuits,
      materials,
      costs
    },
    compliance: complianceNotes,
    recommendations: [
      circuits.total > 30 ? 'Consider sub-panels for large installations' : null,
      totalLoad > 15000 ? 'Verify utility service capacity' : null,
      specialRequirements.length > 0 ? 'Review special requirements with engineer' : null
    ].filter(Boolean),
    accuracy: '±10% (Design Development Level)',
    validUntil: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString() // 30 days
  }
}];

// Merge estimation with historical data
const estimation = $('Load Calculator').first().json;
const historicalResponse = $('Historical Analysis').first();

let historicalData = null;
let calibrationFactor = 1.0;
let riskLevel = 'medium';

// Process historical data if available
if (historicalResponse && historicalResponse.json && !historicalResponse.json.error) {
  historicalData = historicalResponse.json;
  calibrationFactor = historicalData.calibrationFactor || 1.0;
  riskLevel = historicalData.riskLevel || 'medium';

  // Apply calibration to costs
  estimation.calculations.costs.materials = Math.round(estimation.calculations.costs.materials * calibrationFactor);
  estimation.calculations.costs.labor = Math.round(estimation.calculations.costs.labor * calibrationFactor);
  estimation.calculations.costs.total = Math.round(estimation.calculations.costs.total * calibrationFactor);

  // Update accuracy based on historical data
  const accuracyMap = {
    'low': '±15%',
    'medium': '±10%', 
    'high': '±7%'
  };
  estimation.accuracy = accuracyMap[riskLevel] + ' (Calibrated with Historical Data)';
} else {
  // Fallback when historical data unavailable
  estimation.accuracy = '±12% (Base Calculation - Limited Historical Data)';
}

// Add historical insights
const finalEstimation = {
  ...estimation,
  historicalInsights: historicalData ? {
    similarProjects: historicalData.similarProjectsCount || 0,
    averageVariance: historicalData.averageVariance || 'N/A',
    riskFactors: historicalData.riskFactors || [],
    calibrationApplied: true,
    calibrationFactor
  } : {
    similarProjects: 0,
    averageVariance: 'N/A',
    riskFactors: ['Limited historical data available'],
    calibrationApplied: false,
    calibrationFactor: 1.0
  },
  riskLevel,
  generatedBy: 'ElectricalAI Pro N8N Workflow',
  workflowVersion: '1.0.0'
};

return [{ json: finalEstimation }];

// Generate summary response
const data = $input.first().json;

const summary = {
  success: true,
  projectId: data.projectId,
  estimation: {
    totalCost: data.calculations.costs.total,
    materialCost: data.calculations.costs.materials,
    laborCost: data.calculations.costs.labor,
    breakdown: data.calculations.costs.breakdown
  },
  technical: {
    totalLoad: data.calculations.totalLoad,
    circuitCount: data.calculations.circuits.total,
    panelSize: data.calculations.circuits.total > 20 ? '200A' : '100A'
  },
  accuracy: data.accuracy,
  riskLevel: data.riskLevel,
  validUntil: data.validUntil,
  historicalCalibration: data.historicalInsights.calibrationApplied,
  nextSteps: [
    'Review estimation with project stakeholders',
    'Finalize electrical design drawings',
    'Submit for permit application',
    'Schedule material procurement'
  ],
  timestamp: data.timestamp
};

return [{ json: summary }];
